#include "multiplier_style.hpp"
#include <iostream>
using namespace livery;
int main(int argc,char**argv){try{require(argc==2,"Pass game folder");Archive a((fs::path(argv[1])/"vfs.zip").u8string());auto two=stockHudStyle(a,1),four=stockHudStyle(a,0);require(identifyMultiplierStyle(a,two)==1&&identifyMultiplierStyle(a,four)==0,"Style identification failed");size_t count=0;auto &meters=stockMeterStyles();for(auto&e:a.entries)if(e.name.rfind("graphics/be/hud/car/",0)==0&&e.name.find("batchTextures.brres")!=std::string::npos){auto original=a.load(e);for(int style=0;style<2;style++){auto out=multiplierStyleBatch(original,style?two:four);require(identifyMultiplierStyle(a,out)==style,"Wrong style");auto textures=decodeTextures(original);size_t index=0;while(textures.at(index).name!="multiplier")index++;size_t begin=u32(original,12)+u32(original,28+index*24+4),length=u32(original,28+index*24+8);for(size_t i=0;i<original.size();i++)if(i<begin||i>=begin+length)require(original[i]==out[i],"Non-multiplier byte changed");}
  for(int style=0;style<int(meters.size());style++){auto out=meterStyleBatch(original,stockMeterStyle(a,style));require(identifyMeterStyle(a,out)==style,"Wrong meter shape");auto textures=decodeTextures(original);size_t index=0;while(textures.at(index).name!="car_meter")index++;size_t begin=u32(original,12)+u32(original,28+index*24+4),length=u32(original,28+index*24+8);for(size_t i=0;i<original.size();i++)if(i<begin||i>=begin+length)require(original[i]==out[i],"Non-meter byte changed");}
  count++;}require(count>=15,"Missing stock HUD coverage");std::cout<<"PASS both multiplier styles and "<<meters.size()<<" boost meter shapes on "<<count<<" HUD batches; all bytes outside the swapped payload unchanged\n";return 0;}catch(const std::exception&e){std::cerr<<e.what()<<'\n';return 1;}}
